/**
 * Shopify headless bridge — maps the frontend catalog (products.ts) to Shopify
 * variant IDs and builds tokenless cart-permalink checkout URLs.
 *
 * Architecture: the entire storefront (browse, PDP, cart) stays on Next/Vercel.
 * At final checkout we hand the cart to Shopify via a cart permalink
 * (`/cart/{variantId}:{qty},…`) so Shopify owns payment, orders, inventory and
 * the admin panel. No API token ships to the browser — permalinks are public.
 *
 * The variant map is generated by scripts/verify-shopify-map.ts from the live
 * Shopify catalog (Admin API) and cross-checked: every purchasable frontend
 * variant resolves to a real Shopify variant (52/52 at time of writing).
 *
 * Gated behind NEXT_PUBLIC_USE_SHOPIFY_CHECKOUT so the existing Razorpay/COD
 * checkout stays the default until we deliberately flip over.
 */
import { PRODUCTS } from "./products";

export const SHOPIFY_STORE = "8yyp1g-0a.myshopify.com";

/** Flip checkout from the custom Razorpay flow to Shopify's hosted checkout. */
export const USE_SHOPIFY_CHECKOUT =
  process.env.NEXT_PUBLIC_USE_SHOPIFY_CHECKOUT === "1";

