/** Resolve a cart line (frontend skuId + color slug) to a Shopify variant id. */
export function shopifyVariantId(
  skuId: string,
  variantSlug: string | null,
): string | null {
  const sku = PRODUCTS.find((p) => p.id === skuId);
  if (!sku) return null;
  if (variantSlug) {
    const keyed = SHOPIFY_VARIANTS[`${sku.slug}|${variantSlug}`];
    if (keyed) return keyed;
  }
  // single-variant SKU, or colored SKU with no color chosen → base handle
  return SHOPIFY_VARIANTS[sku.slug] ?? null;
}

export type ShopifyCartInput = {
  skuId: string;
  variantSlug: string | null;
  qty: number;
};

/**
 * Build a tokenless Shopify cart permalink from cart lines. Adds every line to
 * the Shopify cart and lands the buyer on Shopify's checkout. Returns null if
 * no line resolves to a variant (caller should fall back to the custom flow).
 */
export function buildShopifyCartUrl(items: ShopifyCartInput[]): string | null {
  const parts: string[] = [];
  for (const i of items) {
    const id = shopifyVariantId(i.skuId, i.variantSlug);
    if (id) parts.push(`${id}:${Math.max(1, Math.floor(i.qty))}`);
  }
  if (!parts.length) return null;
  // `?checkout[email]` etc. could be appended later; storefront=… avoids the
  // "cart" interstitial on some themes. Keep it minimal + reliable for now.
  return `https://${SHOPIFY_STORE}/cart/${parts.join(",")}`;
}
